#define KIND_NAME_ROW(kind, ...) [kind] = #kind,
#define DEFINE_KIND_NAME_TABLE(Name, Enum, COUNT, LIST)                   \
  static const char *const Name##s[COUNT] = { LIST (KIND_NAME_ROW) };     \
  const char *Name (Enum kind) {                                          \
    static char corrupt[32];                                              \
    if ((u32) kind < COUNT) return Name##s[kind];                         \
    snprintf (corrupt, sizeof corrupt, "<corrupt kind %d>", (int) kind);  \
    return corrupt;                                                       \
  }

