typedef enum {
  LEXICAL_CLASS_NONE           = 0,
  LEXICAL_CLASS_UPPER          = 1u << 0,
  LEXICAL_CLASS_LOWER          = 1u << 1,
  LEXICAL_CLASS_DIGIT          = 1u << 2,
  LEXICAL_CLASS_EXTENDED_DIGIT = 1u << 3,
  LEXICAL_CLASS_SEPARATOR      = 1u << 4,
  LEXICAL_CLASS_CONTROL        = 1u << 5,
  LEXICAL_CLASS_IDENTIFIER     = 1u << 6,

  LEXICAL_CLASS_LETTER = LEXICAL_CLASS_UPPER | LEXICAL_CLASS_LOWER
} Lexical_Class_Mask;

const u8 Lexical_Class_Table[256] = {
  [0x00 ... 0x08] = LEXICAL_CLASS_CONTROL,
  [0x09 ... 0x0D] = LEXICAL_CLASS_CONTROL | LEXICAL_CLASS_SEPARATOR,
  [0x0E ... 0x1F] = LEXICAL_CLASS_CONTROL,
  [' ']           = LEXICAL_CLASS_SEPARATOR,

  ['0' ... '9']   = LEXICAL_CLASS_DIGIT | LEXICAL_CLASS_EXTENDED_DIGIT |
                    LEXICAL_CLASS_IDENTIFIER,
  ['A' ... 'F']   = LEXICAL_CLASS_UPPER | LEXICAL_CLASS_EXTENDED_DIGIT |
                    LEXICAL_CLASS_IDENTIFIER,
  ['G' ... 'Z']   = LEXICAL_CLASS_UPPER | LEXICAL_CLASS_IDENTIFIER,
  ['_']           = LEXICAL_CLASS_IDENTIFIER,
  ['a' ... 'f']   = LEXICAL_CLASS_LOWER | LEXICAL_CLASS_EXTENDED_DIGIT |
                    LEXICAL_CLASS_IDENTIFIER,
  ['g' ... 'z']   = LEXICAL_CLASS_LOWER | LEXICAL_CLASS_IDENTIFIER,
  [0x7F]          = LEXICAL_CLASS_CONTROL
};

#define Lexical_Classes(ch) (Lexical_Class_Table[(u8)(ch)])
#define Is_Id_Char(ch)      (Lexical_Classes (ch) & LEXICAL_CLASS_IDENTIFIER)

