typedef enum {
  CONSTRAINT_FORM_NONE              = 0,
  CONSTRAINT_FORM_RANGE             = 1u << 0,
  CONSTRAINT_FORM_FLOATING_ACCURACY = 1u << 1,
  CONSTRAINT_FORM_FIXED_ACCURACY    = 1u << 2,
  CONSTRAINT_FORM_INDEX             = 1u << 3,
  CONSTRAINT_FORM_DISCRIMINANT      = 1u << 4
} Constraint_Form_Kind;

typedef enum {
  PRIVATE_NAME_POSITION_UNCHANGED = 0,
  PRIVATE_NAME_AS_TYPE_MARK,
  PRIVATE_NAME_IN_UNADMITTED_DECLARATION,
  PRIVATE_NAME_IN_DERIVED_TYPE_DEFINITION,
  PRIVATE_NAME_IN_EXPRESSION
} Private_Name_Position;

typedef u32 Node_Class_Mask;
enum {
  NODE_CLASS_NONE = 0,

  NODE_CLASS_ENCLOSES_EXPRESSIONS     = 1u << 0,

  NODE_CLASS_BODY                     = 1u << 1,

  NODE_CLASS_PROGRAM_UNIT_DECLARATION = 1u << 2,

  NODE_CLASS_SUBPROGRAM_SPECIFICATION = 1u << 3,

  NODE_CLASS_SUBPROGRAM_BODY          = 1u << 4,

  NODE_CLASS_SUBPROGRAM_RENAMING      = 1u << 5,

  NODE_CLASS_SIMPLE_OR_EXPANDED_NAME  = 1u << 6,

  NODE_CLASS_SUBPROGRAM_DECLARATION   = NODE_CLASS_SUBPROGRAM_SPECIFICATION |
                                        NODE_CLASS_SUBPROGRAM_BODY |
                                        NODE_CLASS_SUBPROGRAM_RENAMING,

  NODE_CLASS_EXEMPT_FROM_FORCING      = 1u << 7,

  NODE_CLASS_TAKES_TYPE_FROM_CONTEXT  = 1u << 8
};

