struct Type {
  Type_Kind   kind;
  Slice       name;
  Symbol     *defining_symbol;
  u32         size;
  Size_Status size_status;
  u32         alignment;
  u32         specified_bit_size;
  u32         specified_representation_aspects;
  Type_Bound  low_bound;
  Type_Bound  high_bound;
  u128        modulus;
  Type       *base_type;
  Type       *parent_type;

  union {

    struct {
      Index_Info *indices;
      u32    index_count;
      Type  *element_type;
      Type  *unconstrained_base;
      bool        is_constrained;
      bool        is_dimension_row;
      bool        aliased_components;
    } array;

    struct {
      Component_Info *components;
      u32        component_count;
      u32        discriminant_count;
      bool            has_discriminants;
      bool            all_defaults;
      bool            is_constrained;
      Variant_Info   *variants;
      u32        variant_count;
      u32        variant_offset;
      u32        max_variant_size;
      Node    *variant_part_node;
      i64        *disc_constraint_values;
      Node   **disc_constraint_exprs;
      u32       *disc_constraint_preeval;
      bool            has_disc_constraints;
      bool            base_incomplete_at_constraint;
    } record;

    struct {
      Type      *designated_type;
      Symbol    *designated_profile;
      Node      *collection;
      bool       is_general;
      bool       is_access_constant;
      Region     region;
      u32   master_scope_id;
    } access;

    struct {
      Slice *literals;
      u32      literal_count;
      i64      *rep_values;
    } enumeration;

    struct {double delta; double small; int scale;} fixed;

    struct {int digits;} flt;
  };

  bool is_packed;

  Type_Kind partial_view_kind;

  u32 partial_view_discriminant_count;

  bool full_view_arrived;

  Location limited_out_parameter;

  bool                      is_frozen;
  Task_Component_State_Kind task_component_state;
  Controlled_Root_Kind      controlled_root;
  i32                       governing_discriminant_memo;

  i64               storage_size;
  Node             *storage_size_expr;
  const char       *equality_func_name;
  bool              is_generic_formal;
  bool              is_generic_actual_view;
  bool              is_ali_opaque;
  struct Type      *generic_actual;
  bool              formal_private_view;
  struct Type      *generic_formal_disc_view;
  Generic_Def_Kind  generic_formal_class;

  Type **pending_constrained_views;
  u32    pending_constrained_count;

  u64    frame_walk_stamp;
};
