#define For_Each_Parameter_Specification(specifications, spec)             \
  for (u32 spec##_at = 0; spec##_at < (specifications)->count; spec##_at++)\
    for (Node *spec = (specifications)->items[spec##_at],                  \
              **spec##_once = &spec;                                       \
         spec##_once and spec and spec->kind == NK_PARAM_SPEC;             \
         spec##_once = NULL)

