#define Keep_Interpretations_Where(interpretations, meaning, kept, condition) \
  u32 kept = 0;                                                              \
  for (u32 kept##_at = 0; kept##_at < (interpretations)->count; kept##_at++) {\
    const Interpretation *meaning = &(interpretations)->items[kept##_at];     \
    if (condition)                                                           \
      (interpretations)->items[kept++] = (interpretations)->items[kept##_at]; \
  }

