#define BRANCH_WEIGHT_ORDINARY    "2000"
#define BRANCH_WEIGHT_UNCOMMON    "1"
#define BRANCH_WEIGHT_USUAL       "10"

#define BRANCH_WEIGHTING_LIST(_)                                              \
  _ (BRANCH_COLD_WHEN_TRUE,      "!0", BRANCH_WEIGHT_EXCEPTIONAL,             \
                                       BRANCH_WEIGHT_ORDINARY)                \
  _ (BRANCH_COLD_WHEN_FALSE,     "!1", BRANCH_WEIGHT_ORDINARY,                \
                                       BRANCH_WEIGHT_EXCEPTIONAL)             \
  _ (BRANCH_UNLIKELY_WHEN_TRUE,  "!5", BRANCH_WEIGHT_UNCOMMON,                \
                                       BRANCH_WEIGHT_USUAL)                   \
  _ (BRANCH_UNLIKELY_WHEN_FALSE, "!6", BRANCH_WEIGHT_USUAL,                   \
                                       BRANCH_WEIGHT_UNCOMMON)

