#define For_Each_Frame_Symbol(from, var)                                  \
  for (int var##_pass = 0; var##_pass < 2; var##_pass++)                  \
    for (u32 var##_index = 0,                                             \
             var##_count = var##_pass == 0 ? (from)->symbol_count         \
                                           : (from)->frame_var_count;     \
         var##_index < var##_count; var##_index++)                        \
      for (Symbol *var = var##_pass == 0                                  \
                           ? (from)->symbols[var##_index]                 \
                           : (from)->frame_vars[var##_index],             \
                  **var##_once = &var;                                    \
           var##_once and not Symbol_Is_Framed_Outside (var, (from));     \
           var##_once = NULL)

