#define GHS_FLAG_LIST(_)                                                      \
  _ ("-check=",        GLUED, MAPPED,        CHECK_LEVEL,     NULL)           \
  _ ("-cpu=",          GLUED, UNSUPPORTED,   NONE,            NULL)           \
  _ ("-bsp=",          GLUED, UNSUPPORTED,   NONE,            NULL)           \
  _ ("-os_dir=",       GLUED, UNSUPPORTED,   NONE,            NULL)           \
