#define RUNTIME_VOID_HOOK(name, body)                           \
  "define linkonce_odr void @__ada_" name "() {\n"              \
  body                                                          \
  "  ret void\n"                                                \
  "}\n"

#define ADA_LOCK_SPIN_LIMIT "48"

#define ADA_SPIN_LIMIT        "64"
#define ADA_SPIN_BUDGET_HOT   "16384"
#define ADA_SPIN_BUDGET_COLD  "0"

#ifdef _WIN32
  #define ADA_LOCK_ATTEMPT(suffix)                                        \
    "  %rc" suffix " = call i8 @TryAcquireSRWLockExclusive(ptr @__rv_mutex)\n" \
    "  %got" suffix " = icmp ne i8 %rc" suffix ", 0\n"
#else
  #define ADA_LOCK_ATTEMPT(suffix)                                        \
    "  %rc" suffix " = call i32 @pthread_mutex_trylock(ptr @__rv_mutex)\n" \
    "  %got" suffix " = icmp eq i32 %rc" suffix ", 0\n"
#endif

#define RUNTIME_SPINNING_LOCK(block_body)                       \
  "define linkonce_odr void @__ada_rt_lock() {\n"               \
  "entry:\n"                                                    \
  ADA_LOCK_ATTEMPT ("_fast")                                    \
  "  br i1 %got_fast, label %out, label %spin\n"                \
  "spin:\n"                                                     \
  "  %i = phi i32 [ 0, %entry ], [ %i2, %again ]\n"             \
  "  call void @__ada_cpu_relax()\n"                            \
  ADA_LOCK_ATTEMPT ("_spun")                                    \
  "  br i1 %got_spun, label %out, label %more\n"                \
  "more:\n"                                                     \
  "  %i2 = add i32 %i, 1\n"                                     \
  "  %keep = icmp ult i32 %i2, " ADA_LOCK_SPIN_LIMIT "\n"       \
  "  br i1 %keep, label %again, label %block\n"                 \
  "again:\n"                                                    \
  "  br label %spin\n"                                          \
  "block:\n"                                                    \
  block_body                                                    \
  "  br label %out\n"                                           \
  "out:\n"                                                      \
  "  ret void\n"                                                \
  "}\n"

#define RAISE_RUNTIME_IDENTITY(name)                            \
  "  call void @__ada_raise(i64 %" name ")\n"                   \
  "  unreachable\n"
#define RAISE_RUNTIME_EXCEPTION(name, identity)                 \
  "  %" name " = ptrtoint ptr @__exc." identity " to "          \
    PTR_INT_TYPE "\n"                                           \
  RAISE_RUNTIME_IDENTITY (name)

#define ENTRY_CALL_LOCK_PREAMBLE                                \
  "  %self = call ptr @__ada_self()\n"                          \
  "  %tnull = icmp eq ptr %task, null\n"                        \
  "  br i1 %tnull, label %raise_te, label %lock_it\n"           \
  "raise_te:\n"                                                 \
  RAISE_RUNTIME_EXCEPTION ("teid", "tasking_error")             \
  "lock_it:\n"                                                  \
  "  call void @__ada_rt_lock()\n"                              \
  "  %gone = call i1 @__ada_caller_abandoned(ptr %self)\n"      \
  "  br i1 %gone, label %abandoned, label %alive\n"             \
  "abandoned:\n"                                                \
  "  call void @__ada_rt_unlock()\n"

#define MONITOR_FAST_PATH_PROBE                                 \
  "  %mbp = " TASK_FIELD ("%task", MONITOR_BODY) "\n"           \
  "  %mon = load ptr, ptr %mbp\n"                               \
  "  %nomon = icmp eq ptr %mon, null\n"                         \
  "  br i1 %nomon, label %enq, label %monq\n"                   \
  "monq:\n"                                                     \
  "  %mqh = " TASK_FIELD ("%task", RENDEZVOUS_QUEUE_HEAD) "\n"  \
  "  %mq = load ptr, ptr %mqh\n"                                \
  "  %queued = icmp ne ptr %mq, null\n"

#define POISON_CALLER_AND_UNWIND                                \
  "  %papf = " TASK_FIELD ("%task", ABORT_PENDING) "\n"         \
  "  store i8 1, ptr %papf\n"                                   \
  "  call void @__ada_task_signal(ptr %task)\n"                 \
  "  call void @__ada_abort_release_call(ptr %task)\n"          \
  "  call void @__ada_abort_subtree(ptr %task)\n"               \
  "  call void @__ada_rt_broadcast()\n"                         \
  "  br label %fastout\n"                                       \
  "fastout:\n"                                                  \
  "  call void @__ada_rt_unlock()\n"                            \
  "  %fhe = icmp ne i64 %fx, 0\n"                               \
  "  br i1 %fhe, label %fraise, label %fok\n"                   \
  "fraise:\n"                                                   \
  RAISE_RUNTIME_IDENTITY ("fx")                                 \
  "fok:\n"

#define SPIN_THEN_PARK                                          \
  "  %ok = extractvalue { i32, i1 } %got, 1\n"                  \
  "  br i1 %ok, label %out, label %busy\n"                      \
  "busy:\n"                                                     \
  "  %i2 = add i32 %i, 1\n"                                     \
  "  %keep = icmp ult i32 %i2, " ADA_SPIN_BUDGET_HOT "\n"       \
  "  br i1 %keep, label %again, label %park\n"                  \
  "again:\n"                                                    \
  "  call void @__ada_cpu_relax()\n"                            \
  "  br label %try\n"                                           \
  "park:\n"

#define POOL_STORAGE_TYPE   "{ ptr, ptr, ptr, ptr, i64, i32, i64, i64 }"
#define POOL_FIELD(pool, byte_offset, name)                     \
  "  %" name " = getelementptr inbounds i8, ptr " pool          \
    ", i64 " TEXT_OF (byte_offset) "\n"
#define POOL_BUMP_OFFSET            8
#define POOL_BUMP_END_OFFSET        16
#define POOL_CHUNKS_OFFSET          24
#define POOL_NEXT_CHUNK_OFFSET      32
#define POOL_LOCK_OFFSET            40
#define POOL_TAKEN_OFFSET           48
#define POOL_RESERVATION_OFFSET     56
#define POOL_CHUNK_HEADER_BYTES     16
#define POOL_FIRST_CHUNK_BYTES      4096
#define POOL_MAX_CHUNK_BYTES        1048576

#define POOL_MACHINE_SHARE_SHIFT    6

#define POOL_UNKNOWN_MACHINE_BYTES  268435456

#define POOL_RESERVATION_DEFAULT    "zeroinitializer"
#define POOL_RESERVATION_STATED                                 \
  "{ ptr null, ptr null, ptr null, ptr null, i64 0, i32 0,"      \
  " i64 0, i64 -1 }"

#define POOL_BLOCK_ALIGN_BYTES      16u

#define POOL_BLOCK_MAX_BYTES        4096u

#define POOL_LOCK_ACQUIRE(pool, tag)                                        \
  POOL_FIELD (pool, POOL_LOCK_OFFSET, "lock." tag)                          \
  "  %shared." tag " = load atomic i8, ptr @__ada_tasks_started"            \
    " monotonic, align 1\n"                                                 \
  "  %guarded." tag " = icmp ne i8 %shared." tag ", 0\n"                    \
  "  br i1 %guarded." tag ", label %spin." tag ", label %held." tag "\n"    \
  "spin." tag ":\n"                                                         \
  "  %was." tag " = atomicrmw xchg ptr %lock." tag ", i32 1 acquire,"       \
    " align 4\n"                                                            \
  "  %busy." tag " = icmp ne i32 %was." tag ", 0\n"                         \
  "  br i1 %busy." tag ", label %spin." tag ", label %held." tag "\n"       \
  "held." tag ":\n"

#define POOL_LOCK_RELEASE(tag, door, after)                                 \
  "  br i1 %guarded." tag ", label %unlock." door ", label %" after "\n"    \
  "unlock." door ":\n"                                                      \
  "  store atomic i32 0, ptr %lock." tag " release, align 4\n"              \
  "  br label %" after "\n"                                                 \
  after ":\n"

#define POOL_POISON_WORD "-5933422213868888189"
#define POOL_SENTINEL_FIELD(block, name)                                    \
  "  %" name " = getelementptr inbounds i8, ptr " block ", i64 8\n"

#define POOL_SCRUB_CHECKED                                                  \
  POOL_SENTINEL_FIELD ("%head", "live")                                     \
  "  store i64 0, ptr %live  ; recycled: no longer a free block\n"
#define POOL_GUARD_CHECKED                                                  \
  POOL_SENTINEL_FIELD ("%block", "mark")                                    \
  "  %stale = load i64, ptr %mark\n"                                        \
  "  %twice = icmp eq i64 %stale, " POOL_POISON_WORD "\n"                   \
  "  br i1 %twice, label %erroneous, label %push\n"                         \
  "push:\n"
#define POOL_MARK_CHECKED                                                   \
  "  store i64 " POOL_POISON_WORD ", ptr %mark  ; freed\n"
#define POOL_ERRONEOUS_CHECKED                                              \
  "erroneous:\n"                                                            \
  RAISE_RUNTIME_EXCEPTION ("e", "program_error")

#define COLLECTION_MACHINE_UNKNOWN                                          \
  "  %machine = add i64 0, 0  ; the machine does not say how large it is\n"

#if defined(_WIN32)
#define COLLECTION_MACHINE_QUERY                                            \
  "  %status = alloca [64 x i8], align 8  ; MEMORYSTATUSEX\n"               \
  "  store i32 64, ptr %status  ; dwLength\n"                               \
  "  %said = call i32 @GlobalMemoryStatusEx(ptr %status)\n"                 \
  "  %total = getelementptr inbounds i8, ptr %status, i64 8\n"              \
  "  %bytes = load i64, ptr %total  ; ullTotalPhys\n"                       \
  "  %known = icmp ne i32 %said, 0\n"                                       \
  "  %machine = select i1 %known, i64 %bytes, i64 0\n"
#elif defined(_SC_PHYS_PAGES)

#ifdef __APPLE__
#define COLLECTION_PHYS_PAGES_SELECTOR 200
#define COLLECTION_PAGESIZE_SELECTOR    29
#else
#define COLLECTION_PHYS_PAGES_SELECTOR  85
#define COLLECTION_PAGESIZE_SELECTOR    30
#endif
_Static_assert (COLLECTION_PHYS_PAGES_SELECTOR == _SC_PHYS_PAGES,
                "sysconf's _SC_PHYS_PAGES selector is not what is emitted");
_Static_assert (COLLECTION_PAGESIZE_SELECTOR == _SC_PAGESIZE,
                "sysconf's _SC_PAGESIZE selector is not what is emitted");
#define COLLECTION_MACHINE_QUERY                                            \
  "  %pages = call i64 @sysconf(i32 "                                       \
    TEXT_OF (COLLECTION_PHYS_PAGES_SELECTOR) ")  ; _SC_PHYS_PAGES\n"        \
  "  %page = call i64 @sysconf(i32 "                                        \
    TEXT_OF (COLLECTION_PAGESIZE_SELECTOR) ")  ; _SC_PAGESIZE\n"            \
  "  %counted = icmp sgt i64 %pages, 0\n"                                   \
  "  %measured = icmp sgt i64 %page, 0\n"                                   \
  "  %known = and i1 %counted, %measured\n"                                 \
  "  %product = mul i64 %pages, %page\n"                                    \
  "  %machine = select i1 %known, i64 %product, i64 0\n"
#else
#define COLLECTION_MACHINE_QUERY  COLLECTION_MACHINE_UNKNOWN
#endif

#define COLLECTION_RESERVATION_RUNTIME(machine_query)                       \
  "; ---- What a collection may hold (RM 11.1, RM 13.2) ----\n"             \
  "define linkonce_odr i64 @__ada_collection_default_bytes()"               \
    " nounwind noinline cold {\n"                                           \
  "entry:\n"                                                                \
  machine_query                                                             \
  "  %share = lshr i64 %machine, "                                          \
    TEXT_OF (POOL_MACHINE_SHARE_SHIFT) "  ; one collection's share\n"       \
  "  %silent = icmp eq i64 %share, 0\n"                                     \
  "  %answer = select i1 %silent, i64 "                                     \
    TEXT_OF (POOL_UNKNOWN_MACHINE_BYTES) ", i64 %share\n"                   \
  "  ret i64 %answer\n"                                                     \
  "}\n\n"                                                                   \
  "; the reservation is settled the first time a collection asks for\n"     \
  "; storage and never revisited, so the machine is queried once per\n"     \
  "; collection in a whole run\n"                                           \
  "define linkonce_odr i64 @__ada_collection_spare(ptr %pool) nounwind {\n" \
  "entry:\n"                                                                \
  POOL_FIELD ("%pool", POOL_RESERVATION_OFFSET, "reservation")              \
  "  %stated = load i64, ptr %reservation\n"                                \
  "  %unset = icmp eq i64 %stated, 0\n"                                     \
  "  br i1 %unset, label %ask, label %weigh\n"                              \
  "ask:\n"                                                                  \
  "  %default = call i64 @__ada_collection_default_bytes()\n"               \
  "  store i64 %default, ptr %reservation\n"                                \
  "  br label %weigh\n"                                                     \
  "weigh:\n"                                                                \
  "  %bound = phi i64 [ %default, %ask ], [ %stated, %entry ]\n"            \
  POOL_FIELD ("%pool", POOL_TAKEN_OFFSET, "held")                           \
  "  %taken = load i64, ptr %held\n"                                        \
  "  %spare = sub i64 %bound, %taken\n"                                     \
  "  ret i64 %spare\n"                                                      \
  "}\n\n"                                                                   \
  "define linkonce_odr void @__ada_collection_adjust(ptr %pool,"            \
    " i64 %delta) nounwind {\n"                                             \
  "entry:\n"                                                                \
  POOL_FIELD ("%pool", POOL_TAKEN_OFFSET, "held")                           \
  "  %taken = load i64, ptr %held\n"                                        \
  "  %after = add i64 %taken, %delta\n"                                     \
  "  store i64 %after, ptr %held\n"                                         \
  "  ret void\n"                                                            \
  "}\n\n"                                                                   \
  "; A collection a pool cannot serve -- an unconstrained array, a\n"       \
  "; discriminated record, an object above the block cutoff -- is one\n"    \
  "; malloc per object, so it is counted per object too: beside a malloc\n" \
  "; the count is free, and the reservation is the one a pool grows\n"      \
  "; against, so the two routes cannot disagree about the collection.\n"    \
  "define linkonce_odr noalias ptr @__ada_collection_allocate(ptr %pool,"   \
    " i64 %size)" ADA_MAY_RAISE " {\n"                                      \
  "entry:\n"                                                                \
  POOL_LOCK_ACQUIRE ("%pool", "take")                                       \
  "  %spare = call i64 @__ada_collection_spare(ptr %pool)\n"                \
  "  %over = icmp ugt i64 %size, %spare\n"                                  \
  "  br i1 %over, label %refuse, label %charge\n"                           \
  "charge:\n"                                                               \
  "  call void @__ada_collection_adjust(ptr %pool, i64 %size)\n"            \
  POOL_LOCK_RELEASE ("take", "charge", "obtain")                            \
  "  %p = call ptr @malloc (i64 %size)\n"                                   \
  "  %isnull = icmp eq ptr %p, null\n"                                      \
  "  br i1 %isnull, label %refund, label %ok\n"                             \
  "ok:\n"                                                                   \
  "  ret ptr %p\n"                                                          \
  "refuse:\n"                                                               \
  POOL_LOCK_RELEASE ("take", "refuse", "refused")                           \
  "  br label %raise\n"                                                     \
  "refund:\n"                                                               \
  "  %back = sub i64 0, %size\n"                                            \
  POOL_LOCK_ACQUIRE ("%pool", "give")                                       \
  "  call void @__ada_collection_adjust(ptr %pool, i64 %back)\n"            \
  POOL_LOCK_RELEASE ("give", "give", "raise")                               \
  RAISE_RUNTIME_EXCEPTION ("e", "storage_error")                            \
  "}\n\n"                                                                   \
  "define linkonce_odr void @__ada_collection_free(ptr %pool, ptr %p,"      \
    " i64 %size) nounwind {\n"                                              \
  "entry:\n"                                                                \
  "  %absent = icmp eq ptr %p, null\n"                                      \
  "  br i1 %absent, label %done, label %credit\n"                           \
  "credit:\n"                                                               \
  "  %back = sub i64 0, %size\n"                                            \
  POOL_LOCK_ACQUIRE ("%pool", "put")                                        \
  "  call void @__ada_collection_adjust(ptr %pool, i64 %back)\n"            \
  POOL_LOCK_RELEASE ("put", "put", "hand")                                  \
  "  call void @free (ptr %p)\n"                                            \
  "  br label %done\n"                                                      \
  "done:\n"                                                                 \
  "  ret void\n"                                                            \
  "}\n\n"

#define COLLECTION_POOL_RUNTIME(scrub, guard, mark, erroneous, free_attrs)  \
  "; ---- Collection pools (RM 4.8): equal blocks, a chain of chunks ----\n" \
  "@__ada_tasks_started = linkonce_odr global i8 0\n"                       \
  "; every byte a pool holds stays reachable from the chunk chain, so a\n"  \
  "; pool that grows is a pool that is being used, never one that leaks --\n" \
  "; and the chunk is the only granularity the collection is counted at,\n" \
  "; which is why the count can afford to ask the machine how large it is\n" \
  "define linkonce_odr ptr @__ada_pool_extend(ptr %pool, i64 %block)"       \
    " nounwind {\n"                                                         \
  "entry:\n"                                                                \
  "  %least = add i64 %block, " TEXT_OF (POOL_CHUNK_HEADER_BYTES) "\n"      \
  "  %spare = call i64 @__ada_collection_spare(ptr %pool)\n"                \
  "  %short = icmp ult i64 %spare, %least\n"                                \
  "  br i1 %short, label %none, label %room\n"                              \
  "room:\n"                                                                 \
  POOL_FIELD ("%pool", POOL_NEXT_CHUNK_OFFSET, "plan")                      \
  "  %planned = load i64, ptr %plan\n"                                      \
  "  %fresh = icmp eq i64 %planned, 0\n"                                    \
  "  %seeded = select i1 %fresh, i64 " TEXT_OF (POOL_FIRST_CHUNK_BYTES)     \
    ", i64 %planned\n"                                                      \
  "  %over = icmp ugt i64 %seeded, " TEXT_OF (POOL_MAX_CHUNK_BYTES) "\n"    \
  "  %capped = select i1 %over, i64 " TEXT_OF (POOL_MAX_CHUNK_BYTES)        \
    ", i64 %seeded\n"                                                       \
  "  %tight = icmp ult i64 %capped, %least\n"                               \
  "  %sized = select i1 %tight, i64 %least, i64 %capped\n"                  \
  "  %greedy = icmp ugt i64 %sized, %spare\n"                               \
  "  %wanted = select i1 %greedy, i64 %spare, i64 %sized\n"                 \
  "  %chunk = call ptr @malloc (i64 %wanted)\n"                             \
  "  %refused = icmp eq ptr %chunk, null\n"                                 \
  "  br i1 %refused, label %retry, label %adopt\n"                          \
  "retry:\n"                                                                \
  "  %minimal = call ptr @malloc (i64 %least)\n"                            \
  "  %exhausted = icmp eq ptr %minimal, null\n"                             \
  "  br i1 %exhausted, label %none, label %adopt\n"                         \
  "none:\n"                                                                 \
  "  ret ptr null\n"                                                        \
  "adopt:\n"                                                                \
  "  %taken = phi ptr [ %chunk, %room ], [ %minimal, %retry ]\n"            \
  "  %span = phi i64 [ %wanted, %room ], [ %least, %retry ]\n"              \
  "  call void @__ada_collection_adjust(ptr %pool, i64 %span)\n"            \
  POOL_FIELD ("%pool", POOL_CHUNKS_OFFSET, "chain")                         \
  "  %older = load ptr, ptr %chain\n"                                       \
  "  store ptr %older, ptr %taken  ; chunk header: the chunk before it\n"   \
  "  store ptr %taken, ptr %chain\n"                                        \
  "  %payload = getelementptr inbounds i8, ptr %taken, i64 "                \
    TEXT_OF (POOL_CHUNK_HEADER_BYTES) "\n"                                  \
  "  %second = getelementptr inbounds i8, ptr %payload, i64 %block\n"       \
  POOL_FIELD ("%pool", POOL_BUMP_OFFSET, "bump")                            \
  "  store ptr %second, ptr %bump\n"                                        \
  "  %limit = getelementptr inbounds i8, ptr %taken, i64 %span\n"           \
  POOL_FIELD ("%pool", POOL_BUMP_END_OFFSET, "edge")                        \
  "  store ptr %limit, ptr %edge\n"                                         \
  "  %doubled = shl i64 %span, 1\n"                                         \
  "  store i64 %doubled, ptr %plan\n"                                       \
  "  ret ptr %payload\n"                                                    \
  "}\n\n"                                                                   \
  "; The slow half, kept out of line so the fast half needs no frame: one\n" \
  "; more chunk, or the RM 11.1 STORAGE_ERROR for a collection that cannot\n" \
  "; grow.  Two tasks that arrive here together each get a chunk and the\n"  \
  "; loser's remainder is only unused, never unreachable -- it is chained.\n" \
  "define linkonce_odr noalias ptr @__ada_pool_grow(ptr %pool, i64 %block)"  \
    ADA_MAY_RAISE " noinline cold {\n"                                      \
  "entry:\n"                                                                \
  POOL_LOCK_ACQUIRE ("%pool", "grow")                                       \
  "  %made = call ptr @__ada_pool_extend(ptr %pool, i64 %block)\n"          \
  POOL_LOCK_RELEASE ("grow", "grow", "answer")                              \
  "  %refused = icmp eq ptr %made, null\n"                                  \
  "  br i1 %refused, label %exhausted, label %done\n"                       \
  "done:\n"                                                                 \
  "  ret ptr %made\n"                                                       \
  "exhausted:\n"                                                            \
  RAISE_RUNTIME_EXCEPTION ("e", "storage_error")                            \
  "}\n\n"                                                                   \
  "; a block leaves the free list before the caller writes to it, so it\n"  \
  "; aliases nothing the caller already holds -- as new's result must\n"    \
  "define linkonce_odr noalias ptr @__ada_pool_allocate(ptr %pool,"         \
    " i64 %block)" ADA_MAY_RAISE " {\n"                                     \
  "entry:\n"                                                                \
  POOL_LOCK_ACQUIRE ("%pool", "get")                                        \
  "  %head = load ptr, ptr %pool\n"                                         \
  "  %recycled = icmp ne ptr %head, null\n"                                 \
  "  br i1 %recycled, label %reuse, label %carve\n"                         \
  "reuse:\n"                                                                \
  "  %behind = load ptr, ptr %head  ; the link lives in the free block\n"   \
  scrub                                                                     \
  "  store ptr %behind, ptr %pool\n"                                        \
  "  br label %release\n"                                                   \
  "carve:\n"                                                                \
  POOL_FIELD ("%pool", POOL_BUMP_OFFSET, "at")                              \
  "  %here = load ptr, ptr %at\n"                                           \
  POOL_FIELD ("%pool", POOL_BUMP_END_OFFSET, "end")                         \
  "  %stop = load ptr, ptr %end\n"                                          \
  "  %past = getelementptr i8, ptr %here, i64 %block\n"                     \
  "  %room = icmp ule ptr %past, %stop\n"                                   \
  "  br i1 %room, label %take, label %spent\n"                              \
  "take:\n"                                                                 \
  "  store ptr %past, ptr %at\n"                                            \
  "  br label %release\n"                                                   \
  "release:\n"                                                              \
  "  %got = phi ptr [ %head, %reuse ], [ %here, %take ]\n"                  \
  POOL_LOCK_RELEASE ("get", "get", "done")                                  \
  "  ret ptr %got\n"                                                        \
  "spent:\n"                                                                \
  POOL_LOCK_RELEASE ("get", "spent", "empty")                               \
  "  %grown = call ptr @__ada_pool_grow(ptr %pool, i64 %block)\n"           \
  "  ret ptr %grown\n"                                                      \
  "}\n\n"                                                                   \
  "define linkonce_odr void @__ada_pool_free(ptr %pool, ptr %block)"        \
    free_attrs " {\n"                                                       \
  "entry:\n"                                                                \
  "  %absent = icmp eq ptr %block, null\n"                                  \
  "  br i1 %absent, label %done, label %guard\n"                            \
  "guard:\n"                                                                \
  guard                                                                     \
  POOL_LOCK_ACQUIRE ("%pool", "put")                                        \
  "  %head = load ptr, ptr %pool\n"                                         \
  "  store ptr %head, ptr %block\n"                                         \
  mark                                                                      \
  "  store ptr %block, ptr %pool\n"                                         \
  POOL_LOCK_RELEASE ("put", "put", "done")                                  \
  "  ret void\n"                                                            \
  erroneous                                                                 \
  "}\n\n"

#define TASK_MARK_DEAD(completed, terminated, note, state, outcome, retire) \
  "  %" completed " = " TASK_FIELD ("%tcb", COMPLETED) "\n"                 \
  "  store i8 1, ptr %" completed "\n"                                      \
  "  %" terminated " = " TASK_FIELD ("%tcb", TERMINATED) "\n"               \
  "  store i8 1, ptr %" terminated note "\n"                                \
  "  %" state " = " TASK_FIELD ("%tcb", ACTIVATION_STATE) "\n"              \
  "  store atomic i8 " outcome ", ptr %" state " release, align 1\n"        \
  "  call void @__ada_task_signal(ptr %tcb)\n"                              \
  retire                                                                    \
  "  call void @__ada_rt_broadcast()\n"                                     \
  "  call void @__ada_rt_unlock()\n"

#define RENDEZVOUS_QUEUE_UNLINK(match, miss, hit)                \
  "  %qhp = " TASK_FIELD ("%self", RENDEZVOUS_QUEUE_HEAD) "\n"   \
  "  %head0 = load ptr, ptr %qhp\n"                              \
  "  br label %wl\n"                                             \
  "wl:\n"                                                        \
  "  %cur = phi ptr [ %head0, %entry ], [ %nx, %adv ]\n"         \
  "  %prev = phi ptr [ null, %entry ], [ %cur, %adv ]\n"         \
  "  %isnull = icmp eq ptr %cur, null\n"                         \
  "  br i1 %isnull, label %" miss ", label %chk\n"               \
  "chk:\n"                                                       \
  match                                                          \
  "adv:\n"                                                       \
  "  %nxp = " RENDEZVOUS_RECORD_FIELD ("%cur", NEXT) "\n"        \
  "  %nx = load ptr, ptr %nxp\n"                                 \
  "  br label %wl\n"                                             \
  "remove:\n"                                                    \
  "  %curnxp = " RENDEZVOUS_RECORD_FIELD ("%cur", NEXT) "\n"     \
  "  %curnx = load ptr, ptr %curnxp\n"                           \
  "  %ph = icmp eq ptr %prev, null\n"                            \
  "  br i1 %ph, label %rmhead, label %rmmid\n"                   \
  "rmhead:\n"                                                    \
  "  store atomic ptr %curnx, ptr %qhp monotonic, align 8\n"     \
  "  br label %" hit "\n"                                        \
  "rmmid:\n"                                                     \
  "  %prevnxp = " RENDEZVOUS_RECORD_FIELD ("%prev", NEXT) "\n"   \
  "  store ptr %curnx, ptr %prevnxp\n"                           \
  "  br label %" hit "\n"

#define RENDEZVOUS_ENQUEUE(r, tail, append)                            \
  "enq:\n"                                                             \
  "  call void @__ada_set_pending_rendezvous(ptr %self, ptr %rv)\n"    \
  "  %qhp = " TASK_FIELD ("%task", RENDEZVOUS_QUEUE_HEAD) "\n"         \
  "  %head = load ptr, ptr %qhp\n"                                     \
  "  %empty = icmp eq ptr %head, null\n"                               \
  "  br i1 %empty, label %sethead, label %walk\n"                      \
  "sethead:\n"                                                         \
  "  store atomic ptr %rv, ptr %qhp monotonic, align 8\n"              \
  "  br label %enq_done\n"                                             \
  "walk:\n"                                                            \
  "  br label %" r "wl\n"                                              \
  r "wl:\n"                                                            \
  "  %" r "cur = phi ptr [ %head, %walk ], [ %" r "nx, %" r "adv ]\n"  \
  "  %" r "curnxp = " RENDEZVOUS_RECORD_FIELD ("%" r "cur", NEXT) "\n" \
  "  %" r "nx = load ptr, ptr %" r "curnxp\n"                          \
  "  %" tail " = icmp eq ptr %" r "nx, null\n"                         \
  "  br i1 %" tail ", label %" append ", label %" r "adv\n"            \
  r "adv:\n"                                                           \
  "  br label %" r "wl\n"                                              \
  append ":\n"                                                         \
  "  store ptr %rv, ptr %" r "curnxp\n"                                \
  "  br label %enq_done\n"                                             \
  "enq_done:\n"                                                        \
  "  call void @__ada_unpassify(ptr %task)\n"                          \
  "  call void @__ada_rt_broadcast()\n"

#define RUNTIME_SELECT_RETIRE(self, suffix)                          \
  "  %wep" suffix " = " TASK_FIELD (self, ACCEPTING_ENTRY_INDEX) "\n" \
  "  store i64 " TEXT_OF (ACCEPTING_ENTRY_NONE) ", ptr %wep" suffix  \
    "  ; no longer in a selective wait\n"                            \
  "  %olp" suffix " = " TASK_FIELD (self, OPEN_ENTRY_LIST) "\n"      \
  "  store ptr null, ptr %olp" suffix "\n"                           \
  "  %atp" suffix " = " TASK_FIELD (self,                            \
                          AWAITING_TERMINATE_ALTERNATIVE) "\n"       \
  "  store i8 0, ptr %atp" suffix "\n"

#define CV_SLEEPER_RAISE                                                  \
  "  %_cvup = atomicrmw add ptr @__ada_cv_sleepers, i32 1 monotonic\n"
#define CV_SLEEPER_LOWER                                                  \
  "  %_cvdn = atomicrmw sub ptr @__ada_cv_sleepers, i32 1 monotonic\n"
#define CV_SLEEPER_GATE(wake_body)                                        \
  "  %n = load atomic i32, ptr @__ada_cv_sleepers monotonic, align 4\n"   \
  "  %any = icmp ne i32 %n, 0\n"                                          \
  "  br i1 %any, label %wake, label %quiet\n"                             \
  "wake:\n"                                                               \
  wake_body                                                               \
  "  br label %quiet\n"                                                   \
  "quiet:\n"

#define RUNTIME_WORD_WAIT(prologue, sleep_body)                          \
  "define linkonce_odr void @__ada_wait_word(ptr %w, i32 %expected,"     \
    " ptr %parked, i32 %budget) {\n"                                     \
  "entry:\n"                                                             \
  prologue                                                               \
  "  br label %outer\n"                                                  \
  "outer:\n"                                                             \
  "  br label %spin\n"                                                   \
  "spin:\n"                                                              \
  "  %i = phi i32 [ 0, %outer ], [ %i2, %again ]\n"                      \
  "  %v = load atomic i32, ptr %w acquire, align 4\n"                    \
  "  %done = icmp ne i32 %v, %expected\n"                                \
  "  br i1 %done, label %out, label %pause\n"                            \
  "pause:\n"                                                             \
  "  %i2 = add i32 %i, 1\n"                                              \
  "  %more = icmp ult i32 %i2, %budget\n"                                \
  "  br i1 %more, label %again, label %park\n"                           \
  "again:\n"                                                             \
  "  call void @__ada_cpu_relax()\n"                                     \
  "  br label %spin\n"                                                   \
  "park:\n"                                                              \
  "  %_up = atomicrmw add ptr %parked, i32 1 seq_cst\n"                  \
  "  %recheck = load atomic i32, ptr %w seq_cst, align 4\n"              \
  "  %moved = icmp ne i32 %recheck, %expected\n"                         \
  "  br i1 %moved, label %leave, label %sleep\n"                         \
  "sleep:\n"                                                             \
  sleep_body                                                             \
  "  br label %leave\n"                                                  \
  "leave:\n"                                                             \
  "  %_down = atomicrmw sub ptr %parked, i32 1 seq_cst\n"                \
  "  br label %outer\n"                                                  \
  "out:\n"                                                               \
  "  ret void\n"                                                         \
  "}\n\n"

#define RUNTIME_WORD_WAKE(wake_body)                                     \
  "define linkonce_odr void @__ada_wake_word(ptr %w, ptr %parked) {\n"   \
  "entry:\n"                                                             \
  "  fence seq_cst\n"                                                    \
  "  %asleep = load atomic i32, ptr %parked seq_cst, align 4\n"          \
  "  %any = icmp ne i32 %asleep, 0\n"                                    \
  "  br i1 %any, label %rouse, label %out\n"                             \
  "rouse:\n"                                                             \
  wake_body                                                              \
  "  br label %out\n"                                                    \
  "out:\n"                                                               \
  "  ret void\n"                                                         \
  "}\n\n"

#define RUNTIME_WORD_PORTABLE                                            \
  "define linkonce_odr void @__ada_wait_word(ptr %w, i32 %expected,"     \
    " ptr %parked, i32 %budget) {\n"                                     \
  "entry:\n"                                                             \
  "  call void @__ada_rt_lock()\n"                                       \
  "  br label %loop\n"                                                   \
  "loop:\n"                                                              \
  "  %v = load atomic i32, ptr %w acquire, align 4\n"                    \
  "  %done = icmp ne i32 %v, %expected\n"                                \
  "  br i1 %done, label %out, label %wait\n"                             \
  "wait:\n"                                                              \
  "  call void @__ada_rt_wait()\n"                                       \
  "  br label %loop\n"                                                   \
  "out:\n"                                                               \
  "  call void @__ada_rt_unlock()\n"                                     \
  "  ret void\n"                                                         \
  "}\n\n"                                                                \
  "; every caller stores the word under the runtime lock, so a broadcast\n" \
  "; here cannot race the waiter's re-test above\n"                      \
  "define linkonce_odr void @__ada_wake_word(ptr %w, ptr %parked) {\n"   \
  "  call void @__ada_rt_broadcast()\n"                                  \
  "  ret void\n"                                                         \
  "}\n\n"

